/* From Uiverse.io by martinval9 - Tags: card */
.__UIV_SCOPE__ .card {
 width: 190px;
 height: 254px;
 background: rgb(40,40,55);
 background: linear-gradient(344deg, rgba(40,40,55,1) 0%, rgba(16,16,18,1) 50%);
 box-shadow: 4px 6px 14px #00000036;
 border-radius: 3px;
 color: #F9F9F9;
 padding: 16px;
 transition: all .3s;
}

.__UIV_SCOPE__ .card:hover {
 margin-top: -30px;
}
